[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>The State of Global Education - Infographic</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;600;700;800;900&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --bg-deep: #0B1426;
    --bg-card: #111D35;
    --bg-card-alt: #0E1A30;
    --accent-amber: #F5A623;
    --accent-gold: #FFC107;
    --accent-coral: #FF6347;
    --accent-red: #E74C3C;
    --accent-teal: #14B8A6;
    --accent-blue: #3B82F6;
    --text-white: #FFFFFF;
    --text-light: #E2E8F0;
    --text-muted: #94A3B8;
    --text-dim: #64748B;
    --divider: #1E3A5F;
  }

  body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    background: var(--bg-deep);
    color: var(--text-white);
    width: 2400px;
    height: 3394px;
    overflow: hidden;
    -webkit-font-smoothing: antialiased;
  }

  .poster {
    width: 2400px;
    height: 3394px;
    padding: 80px 100px 60px;
    display: flex;
    flex-direction: column;
    position: relative;
    background:
      radial-gradient(ellipse at 20% 10%, rgba(245,166,35,0.06) 0%, transparent 50%),
      radial-gradient(ellipse at 80% 90%, rgba(255,99,71,0.05) 0%, transparent 50%),
      var(--bg-deep);
  }

  /* ===== HEADER ===== */
  .header {
    text-align: center;
    padding-bottom: 50px;
    border-bottom: 2px solid var(--divider);
    margin-bottom: 50px;
    position: relative;
  }

  .header-label {
    font-size: 18px;
    font-weight: 600;
    letter-spacing: 6px;
    text-transform: uppercase;
    color: var(--accent-amber);
    margin-bottom: 20px;
  }

  .header h1 {
    font-size: 82px;
    font-weight: 900;
    line-height: 1.05;
    letter-spacing: -2px;
    margin-bottom: 16px;
    background: linear-gradient(135deg, #FFFFFF 0%, #CBD5E1 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .header-subtitle {
    font-size: 28px;
    font-weight: 300;
    color: var(--text-muted);
    max-width: 1400px;
    margin: 0 auto;
    line-height: 1.5;
  }

  .header-divider-accent {
    width: 120px;
    height: 4px;
    background: linear-gradient(90deg, var(--accent-amber), var(--accent-coral));
    border-radius: 2px;
    margin: 24px auto 0;
  }

  /* ===== SECTIONS ===== */
  .section {
    margin-bottom: 40px;
    position: relative;
  }

  .section-label {
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: var(--accent-amber);
    margin-bottom: 12px;
  }

  .section-title {
    font-size: 36px;
    font-weight: 800;
    color: var(--text-white);
    margin-bottom: 24px;
    line-height: 1.2;
  }

  /* ===== HISTORICAL PROGRESS ===== */
  .progress-section {
    background: var(--bg-card);
    border-radius: 24px;
    padding: 50px 60px;
    position: relative;
    overflow: hidden;
  }

  .progress-section::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, var(--accent-coral), var(--accent-amber), var(--accent-teal));
  }

  .progress-row {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 60px;
    margin-top: 30px;
  }

  .progress-block {
    text-align: center;
    flex: 1;
  }

  .progress-year {
    font-size: 22px;
    font-weight: 600;
    color: var(--text-muted);
    margin-bottom: 12px;
    letter-spacing: 2px;
  }

  .progress-number {
    font-size: 96px;
    font-weight: 900;
    line-height: 1;
    margin-bottom: 12px;
  }

  .progress-number.negative {
    color: var(--accent-coral);
  }

  .progress-number.positive {
    color: var(--accent-teal);
  }

  .progress-desc {
    font-size: 22px;
    color: var(--text-muted);
    font-weight: 400;
  }

  .progress-arrow {
    font-size: 64px;
    color: var(--accent-amber);
    font-weight: 300;
    flex-shrink: 0;
  }

  /* Icon array for 1-in-5 vs 4-in-5 */
  .icon-arrays {
    display: flex;
    justify-content: center;
    gap: 80px;
    margin-top: 40px;
  }

  .icon-array {
    display: flex;
    gap: 10px;
    align-items: center;
  }

  .icon-person {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .icon-person.lit {
    background: var(--accent-amber);
  }

  .icon-person.dim {
    background: rgba(255,255,255,0.1);
  }

  .icon-person.teal-lit {
    background: var(--accent-teal);
  }

  .icon-array-label {
    font-size: 16px;
    color: var(--text-dim);
    margin-top: 8px;
    text-align: center;
  }

  /* ===== 244 MILLION — DOMINANT STAT ===== */
  .out-of-school-section {
    background: linear-gradient(135deg, #1A0A0A 0%, var(--bg-card) 50%, #1A0A0A 100%);
    border-radius: 24px;
    padding: 60px;
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(255,99,71,0.2);
  }

  .out-of-school-section::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle at 50% 50%, rgba(255,99,71,0.08) 0%, transparent 40%);
    pointer-events: none;
  }

  .big-stat {
    font-size: 180px;
    font-weight: 900;
    line-height: 0.95;
    color: var(--accent-coral);
    text-shadow: 0 0 80px rgba(255,99,71,0.3);
    position: relative;
  }

  .big-stat-unit {
    font-size: 48px;
    font-weight: 700;
    color: var(--accent-coral);
    letter-spacing: 4px;
    text-transform: uppercase;
    margin-top: 8px;
    position: relative;
  }

  .big-stat-desc {
    font-size: 30px;
    font-weight: 400;
    color: var(--text-light);
    margin-top: 16px;
    position: relative;
  }

  .breakdown-row {
    display: flex;
    justify-content: center;
    gap: 60px;
    margin-top: 40px;
    position: relative;
  }

  .breakdown-item {
    text-align: center;
    padding: 24px 40px;
    background: rgba(255,255,255,0.04);
    border-radius: 16px;
    border: 1px solid rgba(255,255,255,0.06);
    min-width: 300px;
  }

  .breakdown-number {
    font-size: 56px;
    font-weight: 800;
    color: var(--accent-coral);
    line-height: 1;
  }

  .breakdown-label {
    font-size: 18px;
    color: var(--text-muted);
    margin-top: 8px;
    font-weight: 400;
  }

  /* ===== LEARNING CRISIS ===== */
  .learning-section {
    background: var(--bg-card);
    border-radius: 24px;
    padding: 44px 60px;
    display: flex;
    align-items: center;
    gap: 50px;
    position: relative;
    overflow: hidden;
  }

  .learning-section::before {
    content: '';
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 6px;
    background: linear-gradient(180deg, var(--accent-amber), var(--accent-coral));
  }

  .learning-left {
    flex: 1;
  }

  .learning-crisis-equation {
    font-size: 40px;
    font-weight: 800;
    margin-bottom: 16px;
  }

  .learning-crisis-equation .enroll {
    color: var(--accent-amber);
  }

  .learning-crisis-equation .neq {
    color: var(--accent-coral);
  }

  .learning-crisis-equation .learn {
    color: var(--accent-coral);
  }

  .learning-stat {
    font-size: 72px;
    font-weight: 900;
    color: var(--accent-coral);
    line-height: 1;
    margin-bottom: 8px;
  }

  .learning-stat-desc {
    font-size: 20px;
    color: var(--text-muted);
    line-height: 1.5;
    max-width: 600px;
  }

  .learning-right {
    flex-shrink: 0;
    width: 400px;
    height: 280px;
  }

  /* ===== QUALITY INEQUALITY ===== */
  .quality-section {
    background: var(--bg-card);
    border-radius: 24px;
    padding: 50px 60px;
    position: relative;
    overflow: hidden;
  }

  .quality-section::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, var(--accent-coral), var(--accent-teal));
  }

  .quality-comparison {
    display: flex;
    gap: 50px;
    margin-top: 30px;
    align-items: stretch;
  }

  .quality-side {
    flex: 1;
    padding: 36px;
    border-radius: 18px;
    position: relative;
  }

  .quality-side.poor {
    background: rgba(255,99,71,0.08);
    border: 1px solid rgba(255,99,71,0.2);
  }

  .quality-side.rich {
    background: rgba(20,184,166,0.08);
    border: 1px solid rgba(20,184,166,0.2);
  }

  .quality-side-label {
    font-size: 18px;
    font-weight: 600;
    letter-spacing: 2px;
    text-transform: uppercase;
    margin-bottom: 16px;
  }

  .quality-side.poor .quality-side-label {
    color: var(--accent-coral);
  }

  .quality-side.rich .quality-side-label {
    color: var(--accent-teal);
  }

  .quality-number {
    font-size: 100px;
    font-weight: 900;
    line-height: 1;
  }

  .quality-side.poor .quality-number {
    color: var(--accent-coral);
  }

  .quality-side.rich .quality-number {
    color: var(--accent-teal);
  }

  .quality-unit {
    font-size: 28px;
    font-weight: 600;
    margin-top: 8px;
  }

  .quality-side.poor .quality-unit {
    color: rgba(255,99,71,0.7);
  }

  .quality-side.rich .quality-unit {
    color: rgba(20,184,166,0.7);
  }

  .quality-desc {
    font-size: 18px;
    color: var(--text-muted);
    margin-top: 16px;
    line-height: 1.5;
  }

  .quality-bar-container {
    margin-top: 20px;
  }

  .quality-bar-bg {
    width: 100%;
    height: 20px;
    background: rgba(255,255,255,0.06);
    border-radius: 10px;
    overflow: hidden;
  }

  .quality-bar-fill {
    height: 100%;
    border-radius: 10px;
  }

  .quality-side.poor .quality-bar-fill {
    width: 25%;
    background: linear-gradient(90deg, var(--accent-coral), #FF8C69);
  }

  .quality-side.rich .quality-bar-fill {
    width: 100%;
    background: linear-gradient(90deg, var(--accent-teal), #5EEAD4);
  }

  .quality-vs {
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .quality-vs-text {
    font-size: 36px;
    font-weight: 800;
    color: var(--text-dim);
    writing-mode: vertical-rl;
    letter-spacing: 4px;
  }

  .quality-middle-row {
    display: flex;
    justify-content: center;
    margin-top: 24px;
  }

  .quality-middle-stat {
    text-align: center;
    padding: 16px 32px;
    background: rgba(255,255,255,0.03);
    border-radius: 12px;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .quality-middle-number {
    font-size: 40px;
    font-weight: 800;
    color: var(--accent-amber);
  }

  .quality-middle-label {
    font-size: 16px;
    color: var(--text-muted);
    margin-top: 4px;
  }

  /* ===== GENDER GAP ===== */
  .gender-section {
    background: var(--bg-card);
    border-radius: 24px;
    padding: 44px 60px;
    position: relative;
  }

  .gender-grid {
    display: flex;
    gap: 30px;
    margin-top: 20px;
  }

  .gender-card {
    flex: 1;
    background: rgba(255,255,255,0.03);
    border-radius: 16px;
    padding: 28px;
    text-align: center;
    border: 1px solid rgba(255,255,255,0.05);
  }

  .gender-level {
    font-size: 20px;
    font-weight: 700;
    color: var(--text-light);
    margin-bottom: 12px;
  }

  .gender-status {
    font-size: 26px;
    font-weight: 800;
    margin-bottom: 8px;
  }

  .gender-status.closed {
    color: var(--accent-teal);
  }

  .status-check {
    display: inline-block;
    width: 28px;
    height: 28px;
    background: var(--accent-teal);
    border-radius: 50%;
    line-height: 28px;
    text-align: center;
    font-size: 16px;
    color: var(--bg-deep);
    font-weight: 900;
    vertical-align: middle;
    margin-right: 8px;
  }

  .gender-detail {
    font-size: 16px;
    color: var(--text-muted);
    line-height: 1.4;
  }

  .gender-exception {
    margin-top: 20px;
    padding: 16px 24px;
    background: rgba(255,99,71,0.06);
    border-radius: 12px;
    border-left: 4px solid var(--accent-coral);
    font-size: 17px;
    color: var(--text-muted);
  }

  .gender-exception strong {
    color: var(--accent-coral);
  }

  /* ===== KEY TAKEAWAY ===== */
  .takeaway-section {
    background: linear-gradient(135deg, var(--bg-card) 0%, #162040 100%);
    border-radius: 24px;
    padding: 44px 60px;
    text-align: center;
    border: 1px solid rgba(245,166,35,0.15);
    position: relative;
    overflow: hidden;
  }

  .takeaway-section::before {
    content: '';
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, var(--accent-amber), var(--accent-coral));
  }

  .takeaway-label {
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: var(--accent-amber);
    margin-bottom: 16px;
  }

  .takeaway-text {
    font-size: 28px;
    font-weight: 400;
    color: var(--text-light);
    line-height: 1.6;
    max-width: 1600px;
    margin: 0 auto;
  }

  .takeaway-text strong {
    color: var(--accent-amber);
    font-weight: 700;
  }

  /* ===== FOOTER ===== */
  .footer {
    margin-top: auto;
    text-align: center;
    padding-top: 30px;
    border-top: 1px solid var(--divider);
  }

  .footer-text {
    font-size: 14px;
    color: var(--text-dim);
    letter-spacing: 1px;
  }

  /* ===== CHART CONTAINERS ===== */
  .chart-container {
    width: 100%;
    height: 100%;
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-label">Global Education Data</div>
    <h1>The State of Global Education</h1>
    <div class="header-subtitle">A comparative look at how far the world has come in expanding education access — and the critical gaps that remain in quality, attendance, and equity.</div>
    <div class="header-divider-accent"></div>
  </div>

  <!-- SECTION 1: HISTORICAL PROGRESS -->
  <div class="section">
    <div class="progress-section">
      <div class="section-label">Historical Transformation</div>
      <div class="section-title">Two Centuries of Educational Expansion</div>
      <div class="progress-row">
        <div class="progress-block">
          <div class="progress-year">1800</div>
          <div class="progress-number negative">&lt; 1 in 5</div>
          <div class="progress-desc">Adults with any formal education</div>
        </div>
        <div class="progress-arrow">&rarr;</div>
        <div class="progress-block">
          <div class="progress-year">Today</div>
          <div class="progress-number positive">&gt; 4 in 5</div>
          <div class="progress-desc">Adults with any formal education</div>
        </div>
      </div>
      <!-- Icon arrays -->
      <div class="icon-arrays">
        <div style="text-align:center;">
          <div class="icon-array">
            <div class="icon-person lit"></div>
            <div class="icon-person dim"></div>
            <div class="icon-person dim"></div>
            <div class="icon-person dim"></div>
            <div class="icon-person dim"></div>
          </div>
          <div class="icon-array-label">1800: 1 in 5 educated</div>
        </div>
        <div style="text-align:center;">
          <div class="icon-array">
            <div class="icon-person teal-lit"></div>
            <div class="icon-person teal-lit"></div>
            <div class="icon-person teal-lit"></div>
            <div class="icon-person teal-lit"></div>
            <div class="icon-person dim"></div>
          </div>
          <div class="icon-array-label">Today: 4 in 5 educated</div>
        </div>
      </div>
    </div>
  </div>

  <!-- SECTION 2: 244 MILLION — DOMINANT -->
  <div class="section">
    <div class="out-of-school-section">
      <div class="section-label" style="position:relative;">The Crisis Today</div>
      <div class="big-stat">244</div>
      <div class="big-stat-unit">Million Children</div>
