#!/usr/bin/env python3
"""Render the poster HTML to PNG using Playwright with debugging."""
import time
from playwright.sync_api import sync_playwright

def render():
    with sync_playwright() as p:
        browser = p.chromium.launch()
        page = browser.new_page(viewport={"width": 2400, "height": 3394})

        # Capture console logs
        page.on("console", lambda msg: print(f"CONSOLE: {msg.type}: {msg.text}"))
        page.on("pageerror", lambda err: print(f"PAGE ERROR: {err}"))

        page.goto("file:///app/output/poster.html", wait_until="networkidle")

        # Wait for fonts and scripts to load
        time.sleep(2)
        page.wait_for_load_state("networkidle")

        # Try to manually trigger chart rendering
        try:
            result = page.evaluate("""() => {
                // Check if AntVInfographic is available
                if (typeof AntVInfographic === 'undefined') return 'AntVInfographic not loaded';
                // Try to check chart container
                const el = document.getElementById('chart-learning');
                if (!el) return 'chart-learning element not found';
                return 'el found, children: ' + el.children.length + ', innerHTML length: ' + el.innerHTML.length;
            }""")
            print(f"Chart status: {result}")
        except Exception as e:
            print(f"Error checking chart: {e}")

        # Wait more for chart rendering
        time.sleep(3)

        # Take screenshot
        page.screenshot(
            path="/app/output/final_poster.png",
            full_page=False,
            clip={"x": 0, "y": 0, "width": 2400, "height": 3394}
        )
        browser.close()
        print("Poster rendered to /app/output/final_poster.png")

if __name__ == "__main__":
    render()

