        <div class="q-side poor">
          <div class="q-label">Poorest Countries</div>
          <div class="q-num">&lt; 3</div>
          <div class="q-unit">years of quality schooling</div>
          <div class="q-note">Parts of Sub-Saharan Africa</div>
          <div class="q-bar">
